import type { ExplanationResult } from "./api/types.ts";
import { languageTier } from "./languages.ts";

export type NextStepPriority = "high" | "medium" | "low";

export interface NextStep {
  id: string;
  title: string;
  detail: string;
  priority: NextStepPriority;
}

/**
 * Personalised next steps, derived only from the backend result.
 *
 * Nothing here is generated by a model and nothing is invented: every step is
 * a consequence of a verified or unverified field the reader can already see.
 * The order is deliberate — an urgent action or an unchecked date outranks a
 * suggestion to read more.
 */
export function buildNextSteps(result: ExplanationResult): NextStep[] {
  const steps: NextStep[] = [];
  const seen = new Set<string>();

  const add = (step: NextStep) => {
    if (seen.has(step.title)) return;
    seen.add(step.title);
    steps.push(step);
  };

  for (const action of result.actions) {
    if (!action.urgent) continue;
    add({
      id: `urgent_${action.id}`,
      title: action.step,
      detail: "Marked urgent in the document. Do this before anything else.",
      priority: "high",
    });
  }

  for (const deadline of result.deadlines) {
    if (deadline.verified) continue;
    add({
      id: `date_${deadline.id}`,
      title: `Check this date: ${deadline.label}${deadline.originalValue ? ` (${deadline.originalValue})` : ""}`,
      detail: "We could not confirm this date in the original text. Compare it with the paper document.",
      priority: "high",
    });
  }

  for (const cost of result.costs) {
    if (cost.verified) continue;
    add({
      id: `cost_${cost.id}`,
      title: `Check this amount: ${cost.label}${cost.originalValue ? ` (${cost.originalValue})` : ""}`,
      detail: "This amount could not be matched to the original. Confirm it before paying.",
      priority: "high",
    });
  }

  const quality = result.languageQuality ?? languageTier(result.lang);
  if (quality === "experimental") {
    add({
      id: "language_quality",
      title: "Read the original or switch language",
      detail: "This language has not been measured yet. Amharic, Oromo, Tigrinya and English have published results.",
      priority: "high",
    });
  }

  const firstDeadline = result.deadlines.find((d) => d.verified && d.originalValue);
  if (firstDeadline) {
    add({
      id: "deadline_plan",
      title: `Plan around ${firstDeadline.label}: ${firstDeadline.originalValue}`,
      detail: "This date is verified in the original. Work backwards from it to pick a submission day.",
      priority: "medium",
    });
  }

  if (result.documentsToBring.length > 0) {
    add({
      id: "documents",
      title: `Prepare ${result.documentsToBring.slice(0, 3).join(", ")}`,
      detail:
        result.documentsToBring.length > 3
          ? `Plus ${result.documentsToBring.length - 3} more item(s) from the Documents to bring card.`
          : "These are the documents the notice says to bring.",
      priority: "medium",
    });
  }

  if (result.howToApply.length > 0) {
    add({
      id: "how_to_apply",
      title: result.howToApply[0],
      detail: "The document states this as the way to apply or submit.",
      priority: "medium",
    });
  }

  for (const warning of result.warnings.slice(0, 2)) {
    add({
      id: `warning_${steps.length}`,
      title: "Read this warning before acting",
      detail: warning,
      priority: "medium",
    });
  }

  if (steps.length === 0) {
    add({
      id: "read_original",
      title: "Check the explanation against the original",
      detail: "No urgent action or unverified field was found. Read the original once before you rely on it.",
      priority: "low",
    });
  }

  return steps.slice(0, 5);
}
